import * as React from "react";
import AppLink from "./AppLink";

type EntityTrustPanelProps = {
  eyebrow: string;
  name: string;
  role?: string;
  summary: string;
  highlights?: string[];
  primaryHref: string;
  primaryLabel: string;
  secondaryHref?: string;
  secondaryLabel?: string;
};

const EntityTrustPanel: React.FC<EntityTrustPanelProps> = ({
  eyebrow,
  name,
  role,
  summary,
  highlights = [],
  primaryHref,
  primaryLabel,
  secondaryHref,
  secondaryLabel,
}) => {
  const cleanHighlights = highlights.filter(Boolean);

  return (
    <section className="w-full max-w-4xl my-8 rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light">
      <p className="text-xs font-semibold uppercase tracking-[0.14em] text-light/50">
        {eyebrow}
      </p>
      <h2 className="mt-2 text-xl font-semibold text-light/90">{name}</h2>
      {role ? <p className="mt-1 text-sm text-light/70">{role}</p> : null}
      <p className="mt-3 text-sm sm:text-base text-light/80 leading-relaxed">
        {summary}
      </p>
      {cleanHighlights.length > 0 ? (
        <ul className="mt-5 grid grid-cols-1 gap-3 sm:grid-cols-3">
          {cleanHighlights.map((item) => (
            <li
              key={item}
              className="rounded-xl border border-black/10 bg-white/50 p-4 text-sm text-light/80"
            >
              {item}
            </li>
          ))}
        </ul>
      ) : null}
      <div className="mt-5 flex flex-wrap gap-3">
        <AppLink
          className="rounded-full bg-secondary px-4 py-2 text-sm text-light"
          to={primaryHref}
        >
          {primaryLabel}
        </AppLink>
        {secondaryHref && secondaryLabel ? (
          <AppLink
            className="rounded-full bg-purplesemilight px-4 py-2 text-sm font-semibold text-dark"
            to={secondaryHref}
          >
            {secondaryLabel}
          </AppLink>
        ) : null}
      </div>
    </section>
  );
};

export default EntityTrustPanel;
